import Database from "better-sqlite3";
import { readFileSync, mkdirSync, readdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DB_PATH = process.env.MC_DB_PATH || join(__dirname, "..", "data", "mission-control.db");

let db;

export function getDb() {
  if (db) return db;

  mkdirSync(dirname(DB_PATH), { recursive: true });
  db = new Database(DB_PATH);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");

  // Run all migrations in order
  const migrationsDir = join(__dirname, "..", "migrations");
  const files = readdirSync(migrationsDir).filter(f => f.endsWith(".sql")).sort();
  for (const file of files) {
    const sql = readFileSync(join(migrationsDir, file), "utf-8");
    db.exec(sql);
  }

  console.log(`[db] SQLite initialized at ${DB_PATH} (${files.length} migrations)`);
  return db;
}

/**
 * middleware.js — Error handling, input sanitization, and validation
 *
 * Three concerns:
 *   1. asyncHandler: wraps route handlers so thrown errors don't crash the process
 *   2. sanitize: strips dangerous content from user/agent input
 *   3. validate: lightweight schema checks for required fields and types
 */

// ══════════════════════════════════════════════════════
// 1. ASYNC ERROR HANDLER
// ══════════════════════════════════════════════════════

/**
 * Wraps an Express route handler so any thrown error (sync or async)
 * is caught and passed to Express's error middleware instead of
 * crashing the process.
 *
 * Usage:
 *   router.get("/foo", asyncHandler((req, res) => { ... }));
 */
export function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

/**
 * Wraps ALL route handlers in an Express Router with asyncHandler.
 * Call this on the router after defining all routes but before exporting.
 *
 * Usage (at the bottom of a route file):
 *   wrapRouter(router);
 *   export default router;
 *
 * This avoids having to wrap each handler individually.
 */
export function wrapRouter(router) {
  const originalRoute = router.route.bind(router);
  router.stack.forEach((layer) => {
    if (layer.route) {
      layer.route.stack.forEach((routeLayer) => {
        const original = routeLayer.handle;
        routeLayer.handle = (req, res, next) => {
          try {
            const result = original(req, res, next);
            // Handle promises (async handlers)
            if (result && typeof result.catch === "function") {
              result.catch(next);
            }
          } catch (err) {
            next(err);
          }
        };
      });
    }
  });
  return router;
}

/**
 * Global error middleware. Mount AFTER all routes in server.js.
 * Logs the full error server-side, sends a safe message to the client.
 */
export function errorMiddleware(err, req, res, _next) {
  const status = err.status || 500;
  const message = status === 500 ? "Internal server error" : err.message;

  console.error(`[ERROR] ${req.method} ${req.path} →`, err.stack || err.message || err);

  res.status(status).json({
    error: message,
    ...(process.env.NODE_ENV !== "production" && { detail: err.message }),
  });
}

/**
 * Creates an error with a status code for use with asyncHandler.
 *   throw httpError(404, "Not found");
 */
export function httpError(status, message) {
  const err = new Error(message);
  err.status = status;
  return err;
}


// ══════════════════════════════════════════════════════
// 2. INPUT SANITIZATION
// ══════════════════════════════════════════════════════

/**
 * HTML entity map for escaping dangerous characters.
 * Prevents stored XSS when content is later rendered in the browser.
 */
const HTML_ENTITIES = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#x27;",
};

const ENTITY_REGEX = /[&<>"']/g;

/**
 * Escapes HTML special characters in a string.
 * Safe for rendering in dangerouslySetInnerHTML contexts.
 */
export function escapeHtml(str) {
  if (typeof str !== "string") return str;
  return str.replace(ENTITY_REGEX, (char) => HTML_ENTITIES[char]);
}

/**
 * Strips <script> tags, event handlers, javascript: URLs, and
 * other dangerous patterns from a string. Preserves the text content.
 *
 * This is NOT a full HTML sanitizer — it's a safety net for content
 * that goes through the Markdown renderer or gets stored as-is.
 */
export function stripDangerous(str) {
  if (typeof str !== "string") return str;
  return str
    // Remove <script>...</script> blocks entirely
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "")
    // Remove event handler attributes
    .replace(/\s*on\w+\s*=\s*["'][^"']*["']/gi, "")
    .replace(/\s*on\w+\s*=\s*\S+/gi, "")
    // Remove javascript: URLs
    .replace(/javascript\s*:/gi, "")
    // Remove data: URLs with script content
    .replace(/data\s*:\s*text\/html/gi, "")
    // Remove <iframe>, <embed>, <object>, <form> tags
    .replace(/<\s*\/?\s*(iframe|embed|object|form|base|meta|link)\b[^>]*>/gi, "")
    // Remove style attributes that could do expression() injection
    .replace(/style\s*=\s*["'][^"']*expression\s*\([^)]*\)[^"']*["']/gi, "");
}

/**
 * Sanitizes a value for safe database storage and later rendering.
 * - Strings: strips dangerous HTML patterns
 * - Numbers: coerced or returned as-is
 * - Objects/arrays: recursively sanitized
 * - null/undefined: passed through
 */
export function sanitize(value) {
  if (value === null || value === undefined) return value;
  if (typeof value === "string") return stripDangerous(value);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.map(sanitize);
  if (typeof value === "object") {
    const clean = {};
    for (const [k, v] of Object.entries(value)) {
      clean[k] = sanitize(v);
    }
    return clean;
  }
  return value;
}

/**
 * Middleware that sanitizes req.body on every request.
 * Mount BEFORE routes in server.js.
 */
export function sanitizeBody(req, res, next) {
  if (req.body && typeof req.body === "object") {
    req.body = sanitize(req.body);
  }
  next();
}


// ══════════════════════════════════════════════════════
// 3. VALIDATION
// ══════════════════════════════════════════════════════

/**
 * Lightweight request body validator.
 *
 * Usage:
 *   const err = validate(req.body, {
 *     title:   { required: true, type: "string", maxLength: 500 },
 *     status:  { type: "string", oneOf: ["active", "draft", "paused"] },
 *     priority:{ type: "string", oneOf: ["critical", "high", "medium", "low"] },
 *   });
 *   if (err) return res.status(400).json({ error: err });
 *
 * Returns null if valid, or a string describing the first error found.
 */
export function validate(body, schema) {
  for (const [field, rules] of Object.entries(schema)) {
    const value = body[field];

    // Required check
    if (rules.required && (value === undefined || value === null || value === "")) {
      return `${field} is required`;
    }

    // Skip further checks if field is absent and not required
    if (value === undefined || value === null) continue;

    // Type check
    if (rules.type && typeof value !== rules.type) {
      return `${field} must be a ${rules.type}`;
    }

    // String length
    if (rules.maxLength && typeof value === "string" && value.length > rules.maxLength) {
      return `${field} must be ${rules.maxLength} characters or fewer`;
    }

    if (rules.minLength && typeof value === "string" && value.length < rules.minLength) {
      return `${field} must be at least ${rules.minLength} characters`;
    }

    // Enum / whitelist
    if (rules.oneOf && !rules.oneOf.includes(value)) {
      return `${field} must be one of: ${rules.oneOf.join(", ")}`;
    }

    // Number range
    if (rules.min !== undefined && typeof value === "number" && value < rules.min) {
      return `${field} must be at least ${rules.min}`;
    }
    if (rules.max !== undefined && typeof value === "number" && value > rules.max) {
      return `${field} must be at most ${rules.max}`;
    }

    // Array check
    if (rules.isArray && !Array.isArray(value)) {
      return `${field} must be an array`;
    }
  }
  return null;
}

import { Router } from "express";
import { getDb } from "../db.js";
import { broadcast } from "../services/events.js";
import { wrapRouter } from "../middleware.js";

const router = Router();

// ── LIST ──────────────────────────────────────────────
router.get("/", (req, res) => {
  const db = getDb();
  const agents = db.prepare("SELECT * FROM agents ORDER BY id").all();

  // Attach current task info
  for (const a of agents) {
    if (a.current_task_id) {
      a.current_task = db.prepare("SELECT id, title, pipeline_stage FROM tasks WHERE id = ?")
        .get(a.current_task_id);
    }
    a.active_tasks = db.prepare(
      "SELECT COUNT(*) as count FROM tasks WHERE assigned_agent = ? AND status IN ('assigned','in_progress')"
    ).get(a.id)?.count || 0;
  }

  res.json(agents);
});

// ── UPSERT (used by gateway sync + hooks) ─────────────
router.put("/:id", (req, res) => {
  const db = getDb();
  const { display_name, status, model, current_task_id, session_count, metadata } = req.body;

  const existing = db.prepare("SELECT * FROM agents WHERE id = ?").get(req.params.id);

  if (existing) {
    const updates = [];
    const values = [];
    if (display_name !== undefined) { updates.push("display_name = ?"); values.push(display_name); }
    if (status !== undefined)       { updates.push("status = ?"); values.push(status); }
    if (model !== undefined)        { updates.push("model = ?"); values.push(model); }
    if (current_task_id !== undefined) { updates.push("current_task_id = ?"); values.push(current_task_id); }
    if (session_count !== undefined) { updates.push("session_count = ?"); values.push(session_count); }
    if (metadata !== undefined)     { updates.push("metadata = ?"); values.push(JSON.stringify(metadata)); }

    updates.push("last_heartbeat = datetime('now')");
    values.push(req.params.id);

    if (updates.length > 1) {
      db.prepare(`UPDATE agents SET ${updates.join(", ")} WHERE id = ?`).run(...values);
    }

    // Log status changes
    if (status && status !== existing.status) {
      db.prepare(`
        INSERT INTO activity_log (entity_type, entity_id, action, old_value, new_value, actor, message)
        VALUES ('agent', ?, 'status_changed', ?, ?, 'system', ?)
      `).run(req.params.id, existing.status, status, `Agent ${req.params.id} → ${status}`);
    }
  } else {
    db.prepare(`
      INSERT INTO agents (id, display_name, status, model, current_task_id, session_count, last_heartbeat, metadata)
      VALUES (?, ?, ?, ?, ?, ?, datetime('now'), ?)
    `).run(
      req.params.id,
      display_name || req.params.id,
      status || "unknown",
      model || "",
      current_task_id || null,
      session_count || 0,
      JSON.stringify(metadata || {})
    );
  }

  const agent = db.prepare("SELECT * FROM agents WHERE id = ?").get(req.params.id);
  broadcast("agent:updated", agent);
  res.json(agent);
});

// ── HEARTBEAT ─────────────────────────────────────────
router.post("/:id/heartbeat", (req, res) => {
  const db = getDb();
  db.prepare("UPDATE agents SET last_heartbeat = datetime('now') WHERE id = ?")
    .run(req.params.id);

  if (req.body.status) {
    db.prepare("UPDATE agents SET status = ? WHERE id = ?")
      .run(req.body.status, req.params.id);
  }

  broadcast("agent:heartbeat", { id: req.params.id, at: new Date().toISOString() });
  res.json({ ok: true });
});

wrapRouter(router);
export default router;

import { Router } from "express";
import { getDb } from "../db.js";
import { broadcast } from "../services/events.js";
import { onApprovalGranted, onApprovalDenied } from "../services/dispatcher.js";
import { wrapRouter, validate } from "../middleware.js";

const router = Router();

// ── LIST (default: pending only) ──────────────────────
router.get("/", (req, res) => {
  const db = getDb();
  const { status, type } = req.query;
  const filterStatus = status || "pending";

  let sql = "SELECT * FROM approvals WHERE 1=1";
  const params = [];
  if (filterStatus !== "all") { sql += " AND status = ?"; params.push(filterStatus); }
  if (type) { sql += " AND type = ?"; params.push(type); }
  sql += " ORDER BY CASE urgency WHEN 'critical' THEN 0 WHEN 'urgent' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END, created_at DESC";

  const approvals = db.prepare(sql).all(...params);

  // Hydrate entity info
  for (const a of approvals) {
    if (a.entity_type === "task" && a.entity_id) {
      a.entity = db.prepare("SELECT id, title, pipeline_stage, assigned_agent FROM tasks WHERE id = ?").get(a.entity_id);
    } else if (a.entity_type === "project" && a.entity_id) {
      a.entity = db.prepare("SELECT id, name, status FROM projects WHERE id = ?").get(a.entity_id);
    } else if (a.entity_type === "request" && a.entity_id) {
      a.entity = db.prepare("SELECT id, title, status, urgency FROM project_requests WHERE id = ?").get(a.entity_id);
    }
  }

  res.json(approvals);
});

// ── GET ONE ───────────────────────────────────────────
router.get("/:id", (req, res) => {
  const db = getDb();
  const a = db.prepare("SELECT * FROM approvals WHERE id = ?").get(req.params.id);
  if (!a) return res.status(404).json({ error: "Approval not found" });
  res.json(a);
});

// ── CREATE (typically by hooks/system, but also manual) ─
router.post("/", (req, res) => {
  const db = getDb();
  const { type, entity_type, entity_id, title, description, urgency, requested_by, resume_token, expires_at, context } = req.body;

  if (!type || !title) return res.status(400).json({ error: "type and title are required" });

  const stmt = db.prepare(`
    INSERT INTO approvals (type, entity_type, entity_id, title, description, urgency, requested_by, resume_token, expires_at, context)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);
  const info = stmt.run(
    type, entity_type || null, entity_id || null,
    title, description || "", urgency || "normal",
    requested_by || "system", resume_token || null,
    expires_at || null, JSON.stringify(context || {})
  );

  const approval = db.prepare("SELECT * FROM approvals WHERE rowid = ?").get(info.lastInsertRowid);

  db.prepare(`
    INSERT INTO activity_log_v2 (entity_type, entity_id, action, new_value, actor, message)
    VALUES ('approval', ?, 'created', 'pending', ?, ?)
  `).run(approval.id, requested_by || "system", `Approval needed: ${title}`);

  broadcast("approval:created", approval);
  res.status(201).json(approval);
});

// ── DECIDE (approve or reject) ────────────────────────
router.post("/:id/decide", (req, res) => {
  const db = getDb();
  const { decision, notes, decided_by } = req.body;
  const approval = db.prepare("SELECT * FROM approvals WHERE id = ?").get(req.params.id);

  if (!approval) return res.status(404).json({ error: "Approval not found" });
  if (approval.status !== "pending") return res.status(422).json({ error: `Already ${approval.status}` });
  if (!["approved", "rejected"].includes(decision)) {
    return res.status(400).json({ error: "Decision must be 'approved' or 'rejected'" });
  }

  db.prepare(`
    UPDATE approvals SET status = ?, decided_by = ?, decision_notes = ?, decided_at = datetime('now')
    WHERE id = ?
  `).run(decision, decided_by || "user", notes || "", req.params.id);

  // Handle side effects based on type
  if (decision === "approved") {
    switch (approval.type) {
      case "task_review": {
        // Move the task to done
        if (approval.entity_id) {
          db.prepare(`
            UPDATE tasks SET pipeline_stage = 'done', status = 'done', completed_at = datetime('now'), updated_at = datetime('now')
            WHERE id = ?
          `).run(approval.entity_id);
          broadcast("task:moved", { taskId: approval.entity_id, from: "review", to: "done" });
        }
        break;
      }
      case "project_approval": {
        // Move project to active
        if (approval.entity_id) {
          db.prepare(`
            UPDATE projects SET status = 'active', updated_at = datetime('now')
            WHERE id = ?
          `).run(approval.entity_id);
          broadcast("project:updated", { id: approval.entity_id, status: "active" });
        }
        break;
      }
      case "request_triage": {
        // Mark request as approved
        if (approval.entity_id) {
          db.prepare(`
            UPDATE project_requests SET status = 'approved', reviewer = ?, updated_at = datetime('now')
            WHERE id = ?
          `).run(decided_by || "user", approval.entity_id);
          broadcast("request:triaged", { id: approval.entity_id, status: "approved" });
        }
        break;
      }
      case "workflow_gate": {
        // The frontend/agent should call the Lobster resume API with the token
        // We just record the decision here
        break;
      }
    }
  } else if (decision === "rejected") {
    switch (approval.type) {
      case "task_review": {
        // Send task back to doing
        if (approval.entity_id) {
          db.prepare(`
            UPDATE tasks SET pipeline_stage = 'doing', status = 'in_progress', updated_at = datetime('now')
            WHERE id = ?
          `).run(approval.entity_id);
          broadcast("task:moved", { taskId: approval.entity_id, from: "review", to: "doing" });
        }
        break;
      }
      case "request_triage": {
        if (approval.entity_id) {
          db.prepare(`
            UPDATE project_requests SET status = 'rejected', reviewer = ?, review_notes = ?, updated_at = datetime('now')
            WHERE id = ?
          `).run(decided_by || "user", notes || "", approval.entity_id);
        }
        break;
      }
    }
  }

  db.prepare(`
    INSERT INTO activity_log_v2 (entity_type, entity_id, action, old_value, new_value, actor, message)
    VALUES ('approval', ?, ?, 'pending', ?, ?, ?)
  `).run(req.params.id, decision, decision, decided_by || "user",
    `${approval.title} → ${decision}${notes ? ": " + notes : ""}`);

  const updated = db.prepare("SELECT * FROM approvals WHERE id = ?").get(req.params.id);
  broadcast(`approval:${decision}`, updated);

  // Dispatch outbound event to agent
  if (decision === "approved") {
    onApprovalGranted(updated);
  } else {
    onApprovalDenied(updated);
  }

  res.json(updated);
});

// ── PENDING COUNT (for badge) ─────────────────────────
router.get("/count/pending", (req, res) => {
  const db = getDb();
  const count = db.prepare("SELECT COUNT(*) as count FROM approvals WHERE status = 'pending'").get().count;
  res.json({ count });
});

wrapRouter(router);
export default router;

import { Router } from "express";
import { getDb } from "../db.js";
import { broadcast } from "../services/events.js";
import { wrapRouter } from "../middleware.js";

const router = Router();

// ── RECORD COST ENTRY (called by hook) ────────────────
router.post("/", (req, res) => {
  const db = getDb();
  const {
    agent_id, task_id, project_id, session_key, model, provider,
    input_tokens, output_tokens, cache_read_tokens, cache_write_tokens,
    input_cost_usd, output_cost_usd, cache_cost_usd, total_cost_usd,
    duration_ms
  } = req.body;

  if (!agent_id) return res.status(400).json({ error: "agent_id is required" });

  // Auto-resolve project_id from task if not provided
  let resolvedProjectId = project_id;
  if (!resolvedProjectId && task_id) {
    const task = db.prepare("SELECT project_id FROM tasks WHERE id = ?").get(task_id);
    resolvedProjectId = task?.project_id || null;
  }

  const stmt = db.prepare(`
    INSERT INTO cost_entries (agent_id, task_id, project_id, session_key, model, provider,
      input_tokens, output_tokens, cache_read_tokens, cache_write_tokens,
      input_cost_usd, output_cost_usd, cache_cost_usd, total_cost_usd, duration_ms)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);
  stmt.run(
    agent_id, task_id || null, resolvedProjectId || null, session_key || null,
    model || "unknown", provider || "",
    input_tokens || 0, output_tokens || 0, cache_read_tokens || 0, cache_write_tokens || 0,
    input_cost_usd || 0, output_cost_usd || 0, cache_cost_usd || 0, total_cost_usd || 0,
    duration_ms || null
  );

  // Update daily aggregate
  const date = new Date().toISOString().slice(0, 10);
  db.prepare(`
    INSERT INTO cost_daily (date, agent_id, model, project_id, total_input, total_output, total_cache, total_cost_usd, run_count)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1)
    ON CONFLICT(date, agent_id, model, project_id)
    DO UPDATE SET
      total_input = total_input + excluded.total_input,
      total_output = total_output + excluded.total_output,
      total_cache = total_cache + excluded.total_cache,
      total_cost_usd = total_cost_usd + excluded.total_cost_usd,
      run_count = run_count + 1
  `).run(date, agent_id, model || "unknown", resolvedProjectId || "",
    input_tokens || 0, output_tokens || 0, (cache_read_tokens || 0) + (cache_write_tokens || 0),
    total_cost_usd || 0);

  broadcast("cost:recorded", { agent_id, model, total_cost_usd, task_id });
  res.status(201).json({ ok: true });
});

// ── DASHBOARD SUMMARY ─────────────────────────────────
router.get("/summary", (req, res) => {
  const db = getDb();
  const { days } = req.query;
  const lookback = parseInt(days) || 30;

  // Total spend
  const total = db.prepare(`
    SELECT COALESCE(SUM(total_cost_usd), 0) as total_cost,
           COALESCE(SUM(input_tokens), 0) as total_input,
           COALESCE(SUM(output_tokens), 0) as total_output,
           COUNT(*) as run_count
    FROM cost_entries
    WHERE created_at >= datetime('now', ?)
  `).get(`-${lookback} days`);

  // Today's spend
  const today = db.prepare(`
    SELECT COALESCE(SUM(total_cost_usd), 0) as cost,
           COUNT(*) as runs
    FROM cost_entries WHERE date(created_at) = date('now')
  `).get();

  // By agent
  const byAgent = db.prepare(`
    SELECT agent_id, SUM(total_cost_usd) as cost, SUM(input_tokens + output_tokens) as tokens, COUNT(*) as runs
    FROM cost_entries WHERE created_at >= datetime('now', ?)
    GROUP BY agent_id ORDER BY cost DESC
  `).all(`-${lookback} days`);

  // By model
  const byModel = db.prepare(`
    SELECT model, SUM(total_cost_usd) as cost, SUM(input_tokens + output_tokens) as tokens, COUNT(*) as runs
    FROM cost_entries WHERE created_at >= datetime('now', ?)
    GROUP BY model ORDER BY cost DESC
  `).all(`-${lookback} days`);

  // By project
  const byProject = db.prepare(`
    SELECT c.project_id, p.name as project_name,
           SUM(c.total_cost_usd) as cost, COUNT(*) as runs
    FROM cost_entries c
    LEFT JOIN projects p ON p.id = c.project_id
    WHERE c.created_at >= datetime('now', ?) AND c.project_id IS NOT NULL
    GROUP BY c.project_id ORDER BY cost DESC
  `).all(`-${lookback} days`);

  // Daily trend (last N days)
  const daily = db.prepare(`
    SELECT date, SUM(total_cost_usd) as cost, SUM(run_count) as runs
    FROM cost_daily
    WHERE date >= date('now', ?)
    GROUP BY date ORDER BY date
  `).all(`-${lookback} days`);

  // Most expensive tasks
  const topTasks = db.prepare(`
    SELECT c.task_id, t.title, SUM(c.total_cost_usd) as cost,
           SUM(c.input_tokens + c.output_tokens) as tokens
    FROM cost_entries c
    JOIN tasks t ON t.id = c.task_id
    WHERE c.created_at >= datetime('now', ?)
    GROUP BY c.task_id ORDER BY cost DESC LIMIT 10
  `).all(`-${lookback} days`);

  res.json({
    period_days: lookback,
    total,
    today,
    byAgent,
    byModel,
    byProject,
    daily,
    topTasks,
  });
});

// ── RAW ENTRIES (for detail drill-down) ───────────────
router.get("/entries", (req, res) => {
  const db = getDb();
  const { agent_id, task_id, project_id, model, limit } = req.query;

  let sql = "SELECT * FROM cost_entries WHERE 1=1";
