/**
 * usePagination — reusable pagination hook for list views
 *
 * Handles offset-based pagination with "Load More" pattern.
 * Tracks total count, loading state, and whether more items exist.
 *
 * Usage:
 *   const { items, loading, hasMore, loadMore, reset, total } = usePagination(
 *     (offset, limit) => api.getDocuments({ offset, limit, ...filters }),
 *     { pageSize: 25 }
 *   );
 */
import { useState, useCallback, useEffect, useRef } from "react";

export default function usePagination(fetchFn, options = {}) {
  const { pageSize = 25, deps = [] } = options;

  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [total, setTotal] = useState(null);
  const offsetRef = useRef(0);

  const load = useCallback(async (reset = false) => {
    if (loading) return;
    setLoading(true);

    try {
      const offset = reset ? 0 : offsetRef.current;
      const data = await fetchFn(offset, pageSize);

      // Handle two response shapes:
      // 1. Array directly: [item, item, ...]
      // 2. Object with items and total: { items: [...], total: N }
      const newItems = Array.isArray(data) ? data : (data?.items || data || []);
      const newTotal = data?.total ?? null;

      if (reset) {
        setItems(newItems);
        offsetRef.current = newItems.length;
      } else {
        setItems(prev => [...prev, ...newItems]);
        offsetRef.current += newItems.length;
      }

      setHasMore(newItems.length >= pageSize);
      if (newTotal !== null) setTotal(newTotal);
    } catch (err) {
      console.error("Pagination load failed:", err);
      setHasMore(false);
    } finally {
      setLoading(false);
    }
  }, [fetchFn, pageSize, loading]);

  // Reset and reload when dependencies change
  useEffect(() => {
    offsetRef.current = 0;
    setItems([]);
    setHasMore(true);
    setTotal(null);

    // Small delay to batch rapid filter changes
    const timer = setTimeout(() => load(true), 50);
    return () => clearTimeout(timer);
  }, deps); // eslint-disable-line react-hooks/exhaustive-deps

  const loadMore = useCallback(() => {
    if (!loading && hasMore) load(false);
  }, [load, loading, hasMore]);

  const reset = useCallback(() => {
    offsetRef.current = 0;
    setItems([]);
    setHasMore(true);
    load(true);
  }, [load]);

  return { items, loading, hasMore, loadMore, reset, total };
}

import { useEffect, useRef, useCallback, useState } from "react";

export function useSSE(onEvent) {
  const [connected, setConnected] = useState(false);
  const sourceRef = useRef(null);
  const cbRef = useRef(onEvent);
  cbRef.current = onEvent;

  useEffect(() => {
    let es;
    let retryTimer;

    function connect() {
      es = new EventSource("/api/events/stream");
      sourceRef.current = es;

      es.onopen = () => setConnected(true);

      // Listen to all event types we care about
      const events = [
        "connected",
        "project:created", "project:updated", "project:deleted", "project:completed",
        "task:created", "task:updated", "task:deleted", "task:moved",
        "task:started", "task:completed", "task:failed", "task:progress", "task:review", "task:stalled",
        "agent:updated", "agent:heartbeat", "agent:idle", "agent:error", "agent:stale",
        "agents:synced",
        "system:health", "system:tick",
        "session.created", "session.ended",
        "request:submitted", "request:triaged", "request:converted", "request:deleted",
        "approval:created", "approval:approved", "approval:rejected",
        "review:submitted", "review:approved", "review:changes_requested", "review:rejected", "review:commented",
        "library:published", "library:updated", "library:deleted",
        "cost:recorded",
      ];

      for (const evt of events) {
        es.addEventListener(evt, (e) => {
          try {
            const data = JSON.parse(e.data);
            cbRef.current?.({ event: evt, data });
          } catch {}
        });
      }

      es.onerror = () => {
        setConnected(false);
        es.close();
        retryTimer = setTimeout(connect, 3000);
      };
    }

    connect();
    return () => {
      clearTimeout(retryTimer);
      es?.close();
    };
  }, []);

  return { connected };
}

